(()=>{if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}else{init()}
function init(){const mm=gsap.matchMedia();mm.add("(max-width: 1079px)",()=>{gsap.registerPlugin(ScrollTrigger);const dom=getDOM();if(!dom)return;const state={isOnTop:!0,scrollLocked:!1,isMenuOpen:!1,activeItem:null,isSubmenuOpen:!1,firstItemsListener:null,secondSubmenuListener:null,accordionTween:null,activeCard:null,acordeonListener:null,};const ctx=gsap.context(()=>{state.animations=createAnimations(dom,state);initEvents(dom,state)},dom.header);return()=>{resetMenu(dom,state);ctx.revert()}})}
function getDOM(){const header=document.getElementById('core-menu-mobile');if(!header)return null;const burgetBtn=document.getElementById('burger-btn');const mobileNavbar=header?.querySelector('.mobile-navbar');const btnPresupuesto=document.querySelector('#aside-menu-btn-test');const mobileMenu=header.querySelector('.mobile-menu');const mobileOverlay=header.querySelector('.menu-overlay');const menuItems=header.querySelectorAll('.menu-item');const menuContainer=header.querySelector('.menu-container');const firstSubmenu=header.querySelector('.first-submenu');const firstSubmenuItems=header.querySelector('.first-submenu-items');const btnBackFirst=firstSubmenu?.querySelector('.btn-back');if(!burgetBtn||!mobileNavbar||!mobileOverlay||!mobileMenu||!menuItems||!firstSubmenu||!firstSubmenuItems||!btnBackFirst||!menuContainer){return null}
return{header,burgetBtn,mobileNavbar,mobileMenu,mobileOverlay,menuItems,firstSubmenu,firstSubmenuItems,btnBackFirst,menuContainer,btnPresupuesto}}
function createAnimations(dom,state){let btnTween=null;const navTween=gsap.to(dom.mobileNavbar,{padding:'12px 16px',duration:0.3,paused:!0});ScrollTrigger.create({trigger:document.body,start:'100px top',end:'max',onUpdate:({direction})=>{if(state.scrollLocked)return;dom.mobileNavbar.classList.toggle('is-scrolled',direction==1);if(direction===1){navTween.play();btnTween?.play();state.isOnTop=!1}else{navTween.reverse();btnTween?.reverse();state.isOnTop=!0}}});gsap.set(dom.mobileMenu,{xPercent:-100,opacity:1,});gsap.set(dom.mobileOverlay,{xPercent:-100,opacity:1,});gsap.set(dom.firstSubmenu,{xPercent:-100,opacity:1,});const menuTL=gsap.timeline({paused:!0,defaults:{ease:'circ.inOut',duration:0.5,}});menuTL.to(dom.mobileOverlay,{xPercent:0,duration:0.3,onStart:()=>{dom.scrollLocked=!0;navTween.play()},onReverseComplete:()=>{dom.scrollLocked=!1;dom.burgetBtn.classList.remove('is-open');dom.mobileNavbar.classList.remove('is-open');state.scrollLocked=!1;if(state.isOnTop)navTween.reverse();if(state.isOnTop)btnTween?.reverse()},}).to(dom.mobileMenu,{xPercent:0,duration:0.5,},"<");const firstSubmenuTL=gsap.timeline({paused:!0,defaults:{ease:'circ.inOut',duration:0.5,}});firstSubmenuTL.to(dom.mobileMenu,{xPercent:100,}).to(dom.firstSubmenu,{xPercent:0,},"<");const chevronTween=(chevron,open)=>{if(!chevron)return
return gsap.to(chevron,{rotate:open?-180:0,duration:0.4,ease:'circ.out',})};if(dom.btnPresupuesto){btnTween=gsap.to(dom.btnPresupuesto,{top:48,duration:0.8,ease:'circ.inOut',paused:!0})}
return{navTween,menuTL,chevronTween,firstSubmenuTL,btnTween}}
function initEvents(dom,state){dom.burgetBtn.addEventListener('click',()=>{onClickOpenMenu(dom,state)});dom.menuItems.forEach(item=>{item.addEventListener('click',(e)=>onMainItemClick(dom,state,item))});dom.btnBackFirst.addEventListener('click',()=>onClickBtnBack(dom,state))}
function initSecondMenuEvent(dom,state){const handler=(e)=>{if(!state.isSubmenuOpen)return;const card=e.target.closest('.card-wrapper');if(!card)return;onClickSubmenuItem(dom,state,card)};dom.firstSubmenuItems.addEventListener('click',handler);return handler};function onClickOpenMenu(dom,state){if(state.isMenuOpen&&state.scrollLocked){closeMenu(dom,state);return}
openMenu(dom,state)}
function openMenu(dom,state){dom.burgetBtn.classList.add('is-open');dom.mobileNavbar.classList.add('is-open');document.body.classList.add('no-scroll');gsap.set(dom.header.querySelector('.menu-container'),{pointerEvents:'auto'});setTimeout(()=>{state.animations.menuTL.play()},100);state.scrollLocked=!0;state.isMenuOpen=!0}
function closeMenu(dom,state){if(state.isSubmenuOpen){closeFirstSubmenu(dom,state)}
state.animations.menuTL.reverse();gsap.set(dom.menuContainer,{clearProps:'pointerEvents'});document.body.classList.remove('no-scroll');state.scrollLocked=!1;state.isMenuOpen=!1}
function onMainItemClick(dom,state,item){const key=item.dataset.menu;if(!key||!MOBILE_MENU_FIRST_SUBMENUS[key])return;openFirstSubmenu(dom,state,item,key)}
function openFirstSubmenu(dom,state,item,key){dom.firstSubmenuItems.innerHTML=MOBILE_MENU_FIRST_SUBMENUS[key];state.animations.firstSubmenuTL.play();state.isSubmenuOpen=!0;state.activeItem=item;state.firstItemsListener=initSecondMenuEvent(dom,state);state.isSecondOpen=!1}
function closeFirstSubmenu(dom,state){if(!state.isSubmenuOpen)return;state.animations.firstSubmenuTL.reverse();if(state.firstItemsListener){dom.firstSubmenuItems.removeEventListener('click',state.firstItemsListener);state.firstItemsListener=null}
state.isSubmenuOpen=!1;state.activeItem=null;if(state.accordionTween){state.accordionTween.kill();state.accordionTween=null;state.activeCard=null}}
function onClickBtnBack(dom,state){closeFirstSubmenu(dom,state)}
function onClickSubmenuItem(dom,state,card){const key=card.dataset.submenu;if(!key||!MOBILE_MENU_SECOND_SUBMENUS[key])return;const cardParent=card.closest('.menu-card');if(!cardParent)return;const accordion=cardParent.querySelector('.second-submenu');if(!accordion)return;if(state.accordionTween){const isSameCard=state.activeCard===card;closeCardAccordion(state);if(isSameCard)return}
openCardAccordion(dom,state,accordion,card,key)}
function openCardAccordion(dom,state,accordion,card,key){accordion.innerHTML=MOBILE_MENU_SECOND_SUBMENUS[key];gsap.set(accordion,{height:0,overflow:"hidden",opacity:1,});const tween=gsap.to(accordion,{height:"auto",duration:0.45,ease:"power3.out",paused:!0});tween.play();state.animations.chevronTween(card.querySelector('.icon svg'),!0);card.classList.add('is-open');state.activeAccordion=accordion;state.accordionTween=tween;state.activeCard=card;state.acordeonListener=clickOnAcordeonItem(dom,state)}
function closeCardAccordion(state){state.accordionTween.reverse();state.animations.chevronTween(state.activeCard.querySelector('.icon svg'),!1)
state.activeCard.classList.remove('is-open');state.accordionTween=null;state.activeCard=null;state.acordeonListener?.destroy();state.acordeonListener=null}
function clickOnAcordeonItem(dom,state){if(!state.activeAccordion)return;const handler=(e)=>{const link=e.target.closest('.second-submenu a');if(!link)return;e.stopPropagation();closeCardAccordion(state);closeMenu(dom,state)};state.activeAccordion.addEventListener('click',handler);return{destroy(){state.activeAccordion.removeEventListener('click',handler)}}}
function resetMenu(dom,state){if(state.animations?.menuTL){state.animations.menuTL.pause(0)}
if(state.animations?.firstSubmenuTL){state.animations.firstSubmenuTL.pause(0)}
if(state.animations?.btnTween){state.animations.btnTween.pause(0)}
dom.burgetBtn.classList.remove('is-open');dom.mobileNavbar.classList.remove('is-open');document.body.classList.remove('no-scroll');gsap.set(dom.menuContainer,{pointerEvents:'none',clearProps:'pointerEvents'});state.isMenuOpen=!1;state.isSubmenuOpen=!1;state.activeCard=null;state.accordionTween=null}})()